DIRS = ["up", "right", "down", "left"]

def magnitude(value):
    if value < 0:
        return -value
    return value

def smaller(left, right):
    if left < right:
        return left
    return right

def route_table(board, width, start):
    visited = {start: [0, None]}
    pending = [start]
    offsets = [-width, 1, width, -1]
    for cell in pending:
        for d in range(4):
            next_cell = cell + offsets[d]
            if next_cell in visited or board[next_cell // width][next_cell % width] != ".":
                continue
            distance = visited[cell][0]
            first = visited[cell][1]
            if first is None:
                first = DIRS[d]
            visited[next_cell] = [distance + 1, first]
            pending.append(next_cell)
    return visited

def decide(state):
    board = state["tiles"]
    width = len(board[0])
    player = state["player"]
    start = player[1] * width + player[0]
    rivals = state["opponents"]
    own_routes = route_table(board, width, start)
    best_merit = -100000
    action = "wait"
    for item in state["items"]:
        cell = item["y"] * width + item["x"]
        if cell == start:
            return "pick"
        if cell not in own_routes:
            continue
        distance = own_routes[cell][0]
        direction = own_routes[cell][1]
        safety = 4
        for index in range(len(rivals)):
            rival = rivals[index]
            remaining = magnitude(item["x"] - rival["x"]) + magnitude(item["y"] - rival["y"])
            if remaining < distance:
                safety = smaller(safety, 0)
            elif remaining == distance:
                priority = (state["turn"] + distance) % (len(rivals) + 1)
                if priority > 0 and index + 1 >= priority:
                    safety = smaller(safety, 1)
                else:
                    safety = smaller(safety, 3)
        merit = safety * 4 - distance * 8
        if merit > best_merit:
            action = direction
            best_merit = merit
    return action
while True:
    action = decide(scan())
    if action == "pick":
        pick()
    elif action == "wait":
        wait()
    else:
        move(action)
